"""Item C, step 1: the frequency module generated by supertile frequencies (uncollared).

M = 9x9 substitution count matrix (spectre_patch.SUBSTITUTIONS; M[i][j] = number of label-j children of label i).
Frequencies of level-k supertiles of label i, per spectre, are u_i * lambda^{-2k} with u the Perron eigenvector of
the child counts normalised so that sum_j u_j s_j = 1, where s_j = spectres per label (2 for Gamma, the mystic).
Since lambda^{-2} = 4 - sqrt15 is a unit of Z[sqrt15], the Z-module they generate is the Z[sqrt15]-module spanned
by the u_i.  We compute it exactly as a lattice in Q(sqrt15) = Q^2 (Hermite normal form of the coordinates).
This is the uncollared module: a submodule of the full patch-frequency (gap-labelling) module, which needs
collared tiles; whether it already equals the full module is the next check.
Prediction (NEXT_STEPS C): contained in (1/N) Z[sqrt15].
Usage: python research/gap_freq.py OUT.json
"""
import sys, json
sys.path.insert(0, ".")
import sympy as sp

def main():
    out = sys.argv[1] if len(sys.argv) > 1 else "gap_freq.json"
    import spectre_patch as spm
    names = spm.TILE_NAMES
    M = sp.zeros(9, 9)
    for i, a in enumerate(names):
        for c in spm.SUBSTITUTIONS[a]:
            if c:
                M[i, names.index(c)] += 1
    r = sp.sqrt(15); lam2 = 4 + r
    # frequency vector v with v M = lam2 v (child counts propagate as row vector)
    ns = (M.T - lam2 * sp.eye(9)).nullspace()
    assert len(ns) == 1, "Perron eigenspace not 1-dimensional"
    v = ns[0]
    s = sp.Matrix([2 if a == "Gamma" else 1 for a in names])
    u = (v / (v.T * s)[0]).applyfunc(lambda x: sp.radsimp(sp.simplify(x)))
    coords = []
    for x in u:
        e = sp.expand(x); b = e.coeff(r); a = sp.expand(e - b * r)
        assert a.is_Rational and b.is_Rational, x
        coords.append((sp.Rational(a), sp.Rational(b)))
    # Z[sqrt15]-span: generators u_i and sqrt15*u_i, as Q^2 vectors (a, b) meaning a + b sqrt15
    gens = []
    for a, b in coords:
        gens += [(a, b), (15 * b, a)]
    N = sp.ilcm(*[sp.fraction(x)[1] for g in gens for x in g])
    G = sp.Matrix([[int(x * N) for x in g] for g in gens])
    from sympy.matrices.normalforms import hermite_normal_form
    H = hermite_normal_form(G.T)  # columns span the lattice
    basis = [[sp.Rational(H[i, j], N) for i in range(2)] for j in range(H.shape[1])]
    res = dict(M=M.tolist(), charpoly=str(sp.factor(M.charpoly().as_expr())),
               u=[str(x) for x in u], u_float=[float(x) for x in u], N=int(N),
               basis=[[str(c) for c in b] for b in basis],
               basis_as_numbers=[f"{b[0]} + {b[1]}*sqrt15" for b in basis])
    print("charpoly", res["charpoly"]); print("u", res["u"]); print("module basis", res["basis_as_numbers"], flush=True)
    # is it a Z[sqrt15]-ideal times 1/N'? report index in (1/N)Z[sqrt15]
    det = abs(sp.Matrix([[b[0] * N, b[1] * N] for b in basis]).det()) if len(basis) == 2 else None
    res["index_in_(1/N)Z[sqrt15]"] = str(det)
    print("N", N, "index", det, flush=True)
    json.dump(res, open(out, "w"), indent=1, default=str)

if __name__ == "__main__":
    main()
